ST.xhtml:p:
R_Trriger1(CLK := g_biDustAbsOpen);
R_Trriger2(CLK := g_biDustAbsClose);
R_Trriger3(CLK := g_biDustVacuumOpen);
R_Trriger4(CLK := g_biDustVacuumClose);
(*R_Trriger5(CLK := g_bLayerEndM);*)
R_Trriger6(CLK := g_biCuttingEnd);


IF R_Trriger1.Q THEN
  g_bDustAbsZeroDone := FALSE;
  g_boDustAbsDone := FALSE;
  nSwitchState := 1;
END_IF;

IF R_Trriger2.Q THEN
  g_boDustAbsDone := FALSE;
  g_bDustAbsZeroDone := FALSE;
END_IF;

IF R_Trriger3.Q THEN
  g_boDustVacuum := TRUE;
END_IF;

IF R_Trriger4.Q THEN
  g_boDustVacuum := FALSE;
END_IF;

(*IF R_Trriger5.Q THEN
  bLayerEnd := TRUE;
END_IF;*)

IF R_Trriger6.Q THEN
  bCuttingEnd := TRUE;
END_IF;

Dust_Override.Enable := TRUE;

CASE nSwitchState OF
  0:
  nSwitchState := 0;
  1:
  IF LREAL_TO_INT(g_fiDustDisType) = 0 THEN
    Dust_Override.VelFactor := 1.0;
    dDustTargetPos := g_dBKheadLength + dFixedBackDis + dDustMargin;
    IF g_dBKheadLength >= dDustDis AND g_dBKheadLength < dDustNotExtendLen THEN
      nSwitchState := 2;
      g_boFixedLenSupportCyl := TRUE;
    ELSIF g_dBKheadLength >= dDustNotExtendLen THEN
      g_boFixedLenSupportCyl := TRUE;
      nSwitchState := 3;
    ELSIF g_dBKheadLength < dDustDis THEN
      nSwitchState := 3;
    END_IF;
    g_nBKCuttingState := 3;
  ELSIF LREAL_TO_INT(g_fiDustDisType) = 1 THEN
    Dust_Override.VelFactor := 1.0;
    dDustTargetPos := g_dBKheadLength + dFixedBackDis + dDustMargin;
    IF g_dBKheadLength < dDustDis AND g_dBKheadLength < dDustNotExtendLen THEN
      nSwitchState := 2;
    ELSE
      nSwitchState := 3;
    END_IF;
    g_nBKCuttingState := 3;
  ELSIF LREAL_TO_INT(g_fiDustDisType) = 2 THEN
    Dust_Override.VelFactor := 1.0;
    dDustTargetPos := g_dBKPartLength + dFixedBackDis + dDustMargin;
    IF g_dBKPartLength >= dDustDis AND g_dBKPartLength < dDustNotExtendLen THEN
      nSwitchState := 2;
      g_boFixedLenSupportCyl := TRUE;
    ELSIF g_dBKPartLength >= dDustNotExtendLen THEN
      g_boFixedLenSupportCyl := TRUE;
      nSwitchState := 3;
    ELSIF g_dBKPartLength < dDustDis THEN
      nSwitchState := 3;
    END_IF;
    g_nBKCuttingState := 3;
  ELSIF LREAL_TO_INT(g_fiDustDisType) = 3 THEN
    Dust_Override.VelFactor := 1.0;
    dDustTargetPos := g_dBKPartLength + dFixedBackDis + dDustMargin;
    IF g_dBKPartLength < dDustDis AND g_dBKPartLength < dDustNotExtendLen THEN
      nSwitchState := 2;
    ELSE
      nSwitchState := 3;
    END_IF;
    g_nBKCuttingState := 3;
  ELSIF LREAL_TO_INT(g_fiDustDisType) = 4 THEN
    dDustTargetPos := 0.0;
    Dust_Override.VelFactor := dDustOverrideValue;
    g_nBKCuttingState := 9;
    nSwitchState := 4;
  ELSIF LREAL_TO_INT(g_fiDustDisType) = 5 THEN
    Dust_Override.VelFactor := 1.0;
    dDustTargetPos := 0.0;
    nSwitchState := 2;
    g_boFixedLenSupportCyl := FALSE;
    g_nBKCuttingState := 17;
  END_IF;
  2:
  DustAbs.Execute := TRUE;
  DustAbs.Position := dDustTargetPos;
  DustAbs.Velocity := dVelocity;

  IF DustAbs.Done THEN
    DustAbs.Execute := FALSE;
    g_boDustAbsDone := TRUE;
    g_nBKCuttingState := 4;
    nSwitchState := 0;
  END_IF;

  IF g_bPlcPauseBuffer THEN
    nSwitchState := 10;
  END_IF;
  IF DustAbs.CommandAborted OR DustAbs.Error THEN
    g_boDustAbsDone := FALSE;
    DustAbs.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
  3:
  g_boDustAbsDone := TRUE;
  4:
  DustAbs.Execute := TRUE;
  DustAbs.Position := dDustTargetPos;
  DustAbs.Velocity := dVelocity;

  IF bCuttingEnd THEN
    Dust_Override.VelFactor := 1.0;
  END_IF;

  IF DustAbs.Done THEN
    DustAbs.Execute := FALSE;
    bLayerEnd := FALSE;
    bCuttingEnd := FALSE;
    g_bDustAbsZeroDone := TRUE;
    g_boFixedLenSupportCyl := FALSE;
    IF g_nBKPipeType=0 THEN
      g_boDustAbsDone := TRUE;
      g_nBKCuttingState := 10;
      nSwitchState := 0;
    ELSIF g_nBKPipeType=1 THEN
      nSwitchState := 20;
    END_IF;
  END_IF;

  IF g_bPlcPauseBuffer THEN
    nSwitchState := 11;
  END_IF;
  IF DustAbs.CommandAborted OR DustAbs.Error THEN
    g_boDustAbsDone := FALSE;
    g_bDustAbsZeroDone := FALSE;
    bCuttingEnd := FALSE;
    DustAbs.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
  10:
  DustAbs.Execute := FALSE;
  Dust_Stop.Execute := TRUE;
  IF Dust_Stop.Done AND g_bPlcStartBuffer THEN
    Dust_Stop.Execute := FALSE;
    nSwitchState := 2;
  END_IF;

  IF Dust_Stop.CommandAborted OR Dust_Stop.Error THEN
    Dust_Stop.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
  11:
  DustAbs.Execute := FALSE;
  Dust_Stop.Execute := TRUE;
  IF Dust_Stop.Done AND g_bPlcStartBuffer THEN
    Dust_Stop.Execute := FALSE;
    nSwitchState := 4;
  END_IF;

  IF Dust_Stop.CommandAborted OR Dust_Stop.Error THEN
    Dust_Stop.Execute := FALSE;
    nSwitchState := 0;
  END_IF;
  20:
  Ton_LubriDelay(IN := TRUE,PT := LREAL_TO_TIME(g_dStartLubriTime));
  IF Ton_LubriDelay.Q THEN
    g_boDustAbsDone := TRUE;
    g_nBKCuttingState := 10;
    Ton_LubriDelay(IN := FALSE);
    nSwitchState := 0;
  END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  DustAbs.Execute := FALSE;
  Dust_Stop.Execute := FALSE;
  nSwitchState := 0;
  g_boDustVacuum := FALSE;
  g_boFixedLenSupportCyl := FALSE;
  g_bDustAbsZeroDone := FALSE;
  bLayerEnd := FALSE;
  bCuttingEnd := FALSE;
  Ton_LubriDelay(IN := FALSE);
  Dust_Override.VelFactor := 1.0;
END_IF;
